import{_ as e,c as i,o as l,ah as a,ao as p,ap as n}from"./chunks/framework.Dq2_gudl.js";const m=JSON.parse('{"title":"Pets in Heaven — آن‌ها، بهشت و اندوه شما","description":"برای کسی که حیوان خانگی‌اش را از دست داده: کتاب مقدس درباره حیوانات، ابدیت و مراقبت خدا چه می‌گوید. چهار نوشته آرام‌بخش.","frontmatter":{"title":"Pets in Heaven — آن‌ها، بهشت و اندوه شما","description":"برای کسی که حیوان خانگی‌اش را از دست داده: کتاب مقدس درباره حیوانات، ابدیت و مراقبت خدا چه می‌گوید. چهار نوشته آرام‌بخش."},"headers":[],"relativePath":"fa/pets-in-heaven/index.md","filePath":"fa/pets-in-heaven/index.md"}'),t={name:"fa/pets-in-heaven/index.md"};function o(c,s,r,d,v,h){return l(),i("div",null,[...s[0]||(s[0]=[a('<div class="pl-quote"><p>«بعد از رفتنش، تنها چیزی که می‌خواستم بدانم این بود: حالش خوب است؟ دوباره همدیگر را می‌بینیم؟»</p><p class="pl-quote-soft">کتاب مقدس با یک جمله به همه پرسش‌ها پاسخ نمی‌دهد، اما نور کافی می‌دهد تا در تاریک‌ترین شب نیز امید را ببینیم.</p></div><section class="pl-section"><h2>پیش از آغاز</h2><p class="pl-lead">این جا جایی نیست که از شما بخواهد «زودتر فراموش کنی». این چهار نوشته برای شماست — کسی که هنوز دلتنگ است.</p><p>از دست دادن یک همراه حیوان، اندوهی بسیار ویژه است. مردم می‌گویند «فقط یک سگ بود» یا «یکی دیگر بگیر» — اما شما می‌دانید که این درست نیست. او صدای قدم‌های شما را می‌شناخت. در سخت‌ترین سال زندگی‌تان، کنار پای شما ماند. آنچه با او رفت، نخستین نگاهی بود که هر صبح به شما خوش‌آمد می‌گفت.</p><p>کتاب مقدس در واقع بسیار درباره حیوانات سخن می‌گوید. خدا آن‌ها را آفرید، به آن‌ها خوراک می‌دهد، با آن‌ها پیمان می‌بندد و آن‌ها را در جهانی قرار می‌دهد که وعده تجدیدش را داده است. این آیات ثابت نمی‌کنند که «هر حیوان خانگی در بهشت است» — کتاب مقدس چنین وعده‌ای نمی‌دهد — اما چیزی مهربان را آشکار می‌کنند: <strong>در نقشه خدا، حیوانات هرگز نقش‌های حاشیه‌ای دورانداختنی نبودند.</strong></p><p>باشد که آنچه اینجا می‌خوانید بیش از آیات باشد — باشد که خدایی باشد که حتی گنجشکی را به یاد می‌آورد، و او را نیز به یاد می‌آورد.</p></section><section class="pl-section"><h2>چهار نوشته برای شما</h2><div class="pl-new-grid"><div class="pl-new-card"><h3><a href="/fa/pets-in-heaven/will-i-see-my-pet-again">آیا دوباره او را خواهم دید؟</a></h3><p>امید کتاب مقدس درباره حیوانات و بهشت — خود آفرینش در انتظار رستگاری است و آفرینش نو هنوز حیوانات را در خود دارد.</p><p class="pl-quote-soft">رومیان ۸:۱۹-۲۲ · اشعیا ۱۱:۶-۹ · مکاشفه ۲۱:۴-۵</p></div><div class="pl-new-card"><h3><a href="/fa/pets-in-heaven/not-one-sparrow-forgotten">حتی یک گنجشک فراموش نمی‌شود</a></h3><p>او خیلی کوچک بود — آیا جهان به یادش خواهد ماند؟ عیسی گفت حتی یک گنجشک نیز بدون آگاهی پدر به زمین نمی‌افتد.</p><p class="pl-quote-soft">متی ۱۰:۲۹-۳۱ · مزامیر ۱۴۷:۹ · مزامیر ۳۶:۶</p></div><div class="pl-new-card"><h3><a href="/fa/pets-in-heaven/rainbow-bridge-covenant">آن سوی پل رنگین‌کمان</a></h3><p>«پل رنگین‌کمان» تصویری زیباست — و کتاب مقدس واقعاً رنگین‌کمان دارد: پیمان جاودان خدا با <em>همه موجودات زنده</em>.</p><p class="pl-quote-soft">پیدایش ۹:۹-۱۳ · اشعیا ۶۵:۲۵ · مکاشفه ۵:۱۳</p></div><div class="pl-new-card"><h3><a href="/fa/pets-in-heaven/permission-to-grieve">اجازه داشتن برای اندوه</a></h3><p>خدا اشک‌های شما را در ظرفی نگه می‌دارد. اندوه نشانه کم‌بودن ایمان نیست؛ عشقی است که ادامه دارد.</p><p class="pl-quote-soft">مزامیر ۵۶:۸ · مزامیر ۳۴:۱۸ · متی ۵:۴</p></div></div></section><section class="pl-section"><h2>چگونه بخوانیم</h2><div class="pl-moment-grid"><div class="pl-moment"><span class="pl-moment-icon">🕯️</span><h3>آهسته — نه یک‌باره همه</h3><p>یک بند کافی است. اگر آیه‌ای ناگهان شما را به گریه انداخت، همان‌جا بایستید. این ضعف نیست؛ این عشق است که جریان دارد.</p></div><div class="pl-moment"><span class="pl-moment-icon">📝</span><h3>نام او را در آیه بگذارید</h3><p>وقتی می‌خوانید «او به چهارپایان خوراک می‌دهد»، نام او را در آن جمله بگویید. خدا همان‌گونه از او مراقبت کرد.</p></div><div class="pl-moment"><span class="pl-moment-icon">🕊️</span><h3>بعد، یک جمله به او بگویید</h3><p>لازم نیست زیبا باشد. «دلتنگت هستم» کافی است. اگر بیشتر می‌خواهید، دفترچه راهنمای PetLoss کنار شما می‌ماند.</p></div></div></section><section class="pl-section"><h2>همهٔ آیات در یک جا</h2><p class="pl-lead">همهٔ آیاتی که در این چهار نوشته آمده، اینجا گرد آمده است تا دوباره بخوانید و آهسته بجویید.</p><div class="pl-verse-groups"><div class="pl-verse-group"><h3><a href="/fa/pets-in-heaven/will-i-see-my-pet-again">آیا دوباره او را خواهم دید؟</a></h3><ul class="pl-verse-list"><li>رومیان ۸:۱۹-۲۲</li><li>اشعیا ۱۱:۶-۹</li><li>مکاشفه ۲۱:۴-۵</li><li>مزامیر ۳۶:۶</li></ul></div><div class="pl-verse-group"><h3><a href="/fa/pets-in-heaven/not-one-sparrow-forgotten">حتی یک گنجشک فراموش نمی‌شود</a></h3><ul class="pl-verse-list"><li>متی ۱۰:۲۹-۳۱</li><li>مزامیر ۱۴۷:۹</li><li>مزامیر ۳۶:۶</li><li>مزامیر ۵۰:۱۰-۱۱</li></ul></div><div class="pl-verse-group"><h3><a href="/fa/pets-in-heaven/rainbow-bridge-covenant">آن سوی پل رنگین‌کمان</a></h3><ul class="pl-verse-list"><li>پیدایش ۹:۹-۱۳</li><li>اشعیا ۶۵:۲۵</li><li>مکاشفه ۵:۱۳</li><li>مزامیر ۱۵۰:۶</li></ul></div><div class="pl-verse-group"><h3><a href="/fa/pets-in-heaven/permission-to-grieve">اجازه داشتن برای اندوه</a></h3><ul class="pl-verse-list"><li>مزامیر ۵۶:۸</li><li>مزامیر ۳۴:۱۸</li><li>مزامیر ۱۴۷:۳</li><li>متی ۵:۴</li><li>یوحنا ۱۱:۳۵</li><li>مکاشفه ۲۱:۴</li></ul></div></div></section><div class="pl-cta"><h2>باشد که اینجا با مهربانی نگه داشته شوید.</h2><p>اگر جایی می‌خواهید برای نگه‌داشتن عکس‌های او و نوشتن حرف‌هایی که فرصت نکردید، PetLoss در سکوت کنار شما می‌ماند — بدون حساب، بدون بارگذاری، کاملاً آفلاین.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">دانلود از App Store</a><p class="pl-disclaimer">این نوشته‌ها تأملی ایمانی و همراهی عاطفی ارائه می‌دهند و جایگزین مشاوره پزشکی، روان‌شناختی یا درمانی نیستند. اگر اندوه مدت‌ها شما را از زندگی بازمی‌دارد، از یک متخصص دارای مجوز یا خط کمک محلی یاری بگیرید. نقل‌قول‌های کتاب مقدس از نسخه King James (KJV) است.</p></div><div class="pl-bible"><h3>بگذارید کلام خدا همراهتان بماند</h3><p>همهٔ آیات این چهار نوشته از کتاب مقدس است. با اپلیکیشن Rainbow Bible می‌توانید هر زمان کتاب مقدس را بخوانید و ویجت «آیهٔ روز» را تنظیم کنید — نوری کوچک برای روزهایی که دلتان تنگ است.</p><div class="pl-bible-shots"><figure><img src="'+p+'" alt="ابزارک Rainbow Bible، آیهٔ ۲ تیموتائوس ۲:۱۳" loading="lazy"><figcaption>آیهٔ روز روی صفحهٔ اصلی</figcaption></figure><figure><img src="'+n+'" alt="اپ Rainbow Bible — موضوع حیوانات خانگی در بهشت، متی ۱۰:۲۹-۳۱" loading="lazy"><figcaption>در موضوع «حیوانات خانگی در بهشت» بخوانید</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">دریافت Rainbow Bible از App Store</a></div>',7)])])}const g=e(t,[["render",o]]);export{m as __pageData,g as default};
